/// <reference types="node" />

import type { OutputFormat, Output, SingleInput } from './types'

export interface ScryptOptions {
  N: number
  r?: number
  p?: number
  dkLen?: number
}

export function scrypt<F extends OutputFormat = 'uint8'>(
  input: SingleInput,
  salt: SingleInput,
  options: ScryptOptions,
  format?: F
): Promise<Output<F>>
